<?php
require_once __DIR__ . '/_init.php';
$erro='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!$admin) { http_response_code(403); exit('Seu perfil está disponível apenas para consulta.'); }
    verify_csrf();
    $nome=trim((string)($_POST['nome']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $senha=(string)($_POST['senha']??''); $conf=(string)($_POST['confirmacao']??'');
    if (mb_strlen($nome)<3 || !filter_var($email,FILTER_VALIDATE_EMAIL)) $erro='Informe um nome válido e um e-mail válido.';
    elseif ($senha!=='' && (strlen($senha)<12 || $senha!==$conf)) $erro='A nova senha deve ter ao menos 12 caracteres e coincidir com a confirmação.';
    else { try { if ($senha!=='') { $s=$pdo->prepare('UPDATE usuarios SET nome=:n,email=:e,senha_hash=:h WHERE id=:id'); $s->execute([':n'=>$nome,':e'=>$email,':h'=>password_hash($senha,PASSWORD_DEFAULT),':id'=>$_SESSION['usuario_id']]); session_regenerate_id(true); } else { $s=$pdo->prepare('UPDATE usuarios SET nome=:n,email=:e WHERE id=:id'); $s->execute([':n'=>$nome,':e'=>$email,':id'=>$_SESSION['usuario_id']]); } $_SESSION['usuario_nome']=$nome; $_SESSION['usuario_email']=$email; header('Location: perfil.php?ok=1'); exit; } catch (PDOException $e) { $erro='Não foi possível atualizar. Verifique se o e-mail já está em uso.'; } }
}
$s=$pdo->prepare('SELECT id,nome,email,perfil,curso,status,criado_em FROM usuarios WHERE id=:id'); $s->execute([':id'=>$_SESSION['usuario_id']]); $u=$s->fetch(); if (!$u || $u['status']!=='ativo') { $_SESSION=[]; session_destroy(); header('Location: ../login.php'); exit; }
admin_header('Meu perfil'); require __DIR__ . '/../../app/Views/admin/perfil_adm.php'; if ($erro): ?><div class="alert error"><?= h($erro) ?></div><?php endif; ?><section class="panel"><h2>Dados da conta</h2><?php if ($admin): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><label>Nome<input name="nome" value="<?= h($u['nome']) ?>" maxlength="150" required></label><label>E-mail<input type="email" name="email" value="<?= h($u['email']) ?>" maxlength="254" required></label><label>Nova senha (opcional)<input type="password" name="senha" minlength="12" autocomplete="new-password"></label><label>Confirme a nova senha<input type="password" name="confirmacao" minlength="12" autocomplete="new-password"></label><button type="submit">Salvar perfil</button></form><?php else: ?><p>Seu perfil está em modo de consulta. Para corrigir algum dado, entre em contato com o administrador.</p><?php endif; ?></section><?php if (!$admin): ?><section class="panel"><h2>Conteúdos do seu curso</h2><?php if (!empty($u['curso'])): $q=$pdo->prepare("SELECT titulo,resumo,imagem_capa,publicado_em FROM conteudos WHERE status='publicado' AND (resumo ILIKE :curso OR corpo ILIKE :curso) ORDER BY publicado_em DESC LIMIT 10"); $q->execute([':curso'=>'%'.$u['curso'].'%']); $posts=$q->fetchAll(); $ev=$pdo->prepare("SELECT titulo,descricao,imagem, data_inicio,local FROM eventos WHERE status='publicado' AND (curso=:curso OR curso IS NULL OR curso='') ORDER BY data_inicio DESC LIMIT 10"); $ev->execute([':curso'=>$u['curso']]); foreach ($posts as $p): ?><article class="item"><h3><?= h($p['titulo']) ?></h3><p><?= h($p['resumo']) ?></p><?php if ($p['imagem_capa']): ?><img class="thumb" src="../<?= h($p['imagem_capa']) ?>" alt="Imagem da notícia"><?php endif; ?></article><?php endforeach; foreach ($ev->fetchAll() as $e): ?><article class="item"><h3><?= h($e['titulo']) ?></h3><p><?= h($e['descricao']) ?></p><p><?= h(date('d/m/Y H:i',strtotime($e['data_inicio']))) ?> · <?= h($e['local']) ?></p><?php if ($e['imagem']): ?><img class="thumb" src="../<?= h($e['imagem']) ?>" alt="Imagem do evento"><?php endif; ?></article><?php endforeach; if (!$posts): ?><p>Não há notícias relacionadas ao curso cadastrado.</p><?php endif; else: ?><p>O curso ainda não foi informado. Peça ao administrador para atualizar seu cadastro.</p><?php endif; ?></section><?php endif; admin_footer();
